const fs = require('fs');
const path = require('path');

// Check for new files in data directory
const dataDir = '/path/to/finance-reconciliation/data';
const files = fs.readdirSync(dataDir);

const csvFiles = files.filter(f => f.endsWith('.csv') || f.endsWith('.xlsx'));

if (csvFiles.length < 2) {
  return [{ json: { error: 'Insufficient files for reconciliation', files: csvFiles } }];
}

// Sort by modification time, newest first
csvFiles.sort((a, b) => {
  const statA = fs.statSync(path.join(dataDir, a));
  const statB = fs.statSync(path.join(dataDir, b));
  return statB.mtime - statA.mtime;
});

return [{
  json: {
    source_file: path.join(dataDir, csvFiles[0]),
    target_file: path.join(dataDir, csvFiles[1]),
    timestamp: new Date().toISOString()
  }
}];

const result = $json;

if (result.stderr && result.stderr.trim()) {
  return [{ json: { success: false, error: result.stderr, stdout: result.stdout, timestamp: new Date().toISOString() } }];
}

return [{ json: { success: true, stdout: result.stdout, timestamp: new Date().toISOString() } }];

