// Archive processed files
const fs = require('fs');
const path = require('path');

const sourceFile = $json.source_file;
const targetFile = $json.target_file;
const archiveDir = '/path/to/finance-reconciliation/data/archive';

if (!fs.existsSync(archiveDir)) {
  fs.mkdirSync(archiveDir, { recursive: true });
}

const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

if (fs.existsSync(sourceFile)) {
  const sourceName = path.basename(sourceFile);
  fs.renameSync(sourceFile, path.join(archiveDir, `${sourceName}.${timestamp}`));
}

if (fs.existsSync(targetFile)) {
  const targetName = path.basename(targetFile);
  fs.renameSync(targetFile, path.join(archiveDir, `${targetName}.${timestamp}`));
}

return [{ json: { archived: true, timestamp: new Date().toISOString() } }];
